<div class="page-title"><div><em>PAYMENTS</em><h1>Send money</h1><p>Move money securely, wherever it needs to go.</p></div></div><div class="grid transfer-grid"><section class="panel form-panel"><div class="tabs" data-ttabs><b data-t="internal" class="active">Internal</b><span data-t="domestic">Domestic</span><span data-t="international">International</span></div><?=form_open('transfer')?><label>From account</label><select name="from_account_id" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=html_escape($a['name'])?> •<?=substr($a['account_number'],-4)?> — <?=money($a['available_balance'])?></option><?php endforeach?></select><label>Saved beneficiary</label><select name="beneficiary_id" data-beneficiary><option value="">Enter a new recipient</option><?php foreach($beneficiaries as $b):?><option value="<?=$b['id']?>" data-name="<?=html_escape($b['name'])?>" data-account="<?=html_escape($b['account_number'])?>" data-bank="<?=html_escape($b['bank_name'])?>"><?=html_escape($b['name'])?></option><?php endforeach?></select><div class="form-grid"><div><label>Recipient name</label><input name="recipient_name" required></div><div><label>Recipient account</label><input name="recipient_account" required></div></div><label>Recipient bank</label><input name="recipient_bank" required><div class="form-grid"><div class="swift-field" hidden><label>SWIFT / BIC code</label><input name="swift_code" placeholder="For international transfers"></div><div><label>Amount</label><input name="amount" type="number" step="0.01" min="0.01" required placeholder="$ 0.00"></div><div><label>Send on</label><input name="scheduled_for" type="date" value="<?=date('Y-m-d')?>" min="<?=date('Y-m-d')?>"></div></div><label>Payment note</label><input name="note" maxlength="255" placeholder="What is this payment for?"><input type="hidden" name="transfer_type" id="transfer-type" value="internal"><button class="btn wide">Review and submit transfer ›</button></form></section><aside class="panel transfer-info"><i>✓</i><h3>Secure transfers</h3><p>Your transfer is protected by multi-layer authentication and continuous fraud monitoring.</p><hr><b>Daily transfer limit</b><div class="progress"><i></i></div><small>$0 used <span>$25,000 limit</span></small></aside></div>
<script>(function(){var tabs=document.querySelector('[data-ttabs]');if(!tabs)return;tabs.querySelectorAll('[data-t]').forEach(function(t){t.addEventListener('click',function(){tabs.querySelectorAll('[data-t]').forEach(function(x){x.classList.toggle('active',x===t)});var type=t.getAttribute('data-t');document.getElementById('transfer-type').value=type;var swift=tabs.closest('.form-panel').querySelector('.swift-field');if(swift)swift.hidden=(type!=='international');});});})();</script>
